insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'documents','게시판 직군별 전체 요구사항 Top 20','<div class="box" style="margin-bottom:16px"><b>게시판 분석 자료</b> · 작성자 관리자 · 게시일 2026-09-12<br><a href="https://grilu.kr/archive/documents/report-demands.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444"> 홈페이지 게시판(노사협의회 공고·회의록 73건, 단체교섭·단체협약 10건, 심의위원회 19건, 노동이사 활동보고 14건, 행정사무감사 회의록 31건)에 실린 노측 건의·요구 사항을 직군별로 모아 정리했습니다. 빈도(반복 제기 횟수)와 최근성(2023년 이후 협의회 안건)을 우선해 순위를 매겼고, 근거가 된 회의·문서를 함께 적었습니다. 연구원(공무직·무기계약직)과 연구위원급(박사급)에 공통되는 항목은 양쪽에 모두 넣었습니다.  1. 연구원(무기계약직·공무직)이 지속적으로 요청하는 사항 Top 20     순위  요구사항  근거(게시판 자료)      1  공무직(연구원) 직급체계 개선 — 연구원(가·나급)·선임연구원 등 승진 경로 신설  2024.10 3차 협의회, 2025.6 2차 협의회 &#x27;직급체계·보수체계 개선 필요성 공감, 지속 논의&#x27;    2  공무직 보수체계 개선 — 승진가급 등 호봉·연봉 조견표 현실화  2025.6 2차 협의회(노측), 2017 계약직 보수 9.9% 인상·경력별 보수체계 현실화 요구    3  근무성적평가 기준 개선 TF 구성 (공무직 평가제도)  2026.5 1차 협의회 — &#x27;TF 추진&#x27; 합의    4  근속수당 및 연구활동비…</p>','관리자',false,'{"legacy_id": "gw-report-demands", "page": "archive/documents/report-demands.html", "files": [], "source": "게시판 분석"}'::jsonb,'2026-09-12'::date,'2026-09-12'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-report-demands');
update public.posts set board='documents', title='게시판 직군별 전체 요구사항 Top 20', content='<div class="box" style="margin-bottom:16px"><b>게시판 분석 자료</b> · 작성자 관리자 · 게시일 2026-09-12<br><a href="https://grilu.kr/archive/documents/report-demands.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444"> 홈페이지 게시판(노사협의회 공고·회의록 73건, 단체교섭·단체협약 10건, 심의위원회 19건, 노동이사 활동보고 14건, 행정사무감사 회의록 31건)에 실린 노측 건의·요구 사항을 직군별로 모아 정리했습니다. 빈도(반복 제기 횟수)와 최근성(2023년 이후 협의회 안건)을 우선해 순위를 매겼고, 근거가 된 회의·문서를 함께 적었습니다. 연구원(공무직·무기계약직)과 연구위원급(박사급)에 공통되는 항목은 양쪽에 모두 넣었습니다.  1. 연구원(무기계약직·공무직)이 지속적으로 요청하는 사항 Top 20     순위  요구사항  근거(게시판 자료)      1  공무직(연구원) 직급체계 개선 — 연구원(가·나급)·선임연구원 등 승진 경로 신설  2024.10 3차 협의회, 2025.6 2차 협의회 &#x27;직급체계·보수체계 개선 필요성 공감, 지속 논의&#x27;    2  공무직 보수체계 개선 — 승진가급 등 호봉·연봉 조견표 현실화  2025.6 2차 협의회(노측), 2017 계약직 보수 9.9% 인상·경력별 보수체계 현실화 요구    3  근무성적평가 기준 개선 TF 구성 (공무직 평가제도)  2026.5 1차 협의회 — &#x27;TF 추진&#x27; 합의    4  근속수당 및 연구활동비…</p>', attachments='{"legacy_id": "gw-report-demands", "page": "archive/documents/report-demands.html", "files": [], "source": "게시판 분석"}'::jsonb where attachments->>'legacy_id' = 'gw-report-demands' and (board <> 'documents' or attachments->>'page' <> 'archive/documents/report-demands.html');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'committee','26-4차 심의위원회 상정(안) 게시 및 직원 의견청취 안','<div class="box" style="margin-bottom:16px"><b>심의위원회 상정(안)</b> · 작성자 장소희 · 게시일 2026-09-08<br><a href="https://grilu.kr/gri/committee/000000oz2.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">심의위원회 상정(안)을 붙임과 같이 게시합니다. 
 ○ 안 건 : 5건 
 - 정관 일부개정안 
 - 경기도 공공투자관리센터운영규정 일부개정안 
 - 보수규정 일부개정안 
 - 간행물관리규칙 일부개정안 
 - 공정거래자율준수 프로그램 운영규칙 제정안 
 안건에 대한 의견이 있는 직원은 양식에 따라  26.9.9(수) 10시30분까지  의견을 제출하여 주시기 바랍니다. 
 *의견 제출방법: 
 (양식)심의위원회 안건 관련 의견 작성→담당자 메일로 제출(인사총무부 장소희, jsh731@gri.kr) 
 감사합니다.</p><p class="note">첨부: 심의위원회 심의안건(26-4차).pdf, (양식) 심의위원회 안건 관련 의견 작성 양식.hwpx</p>','장소희',false,'{"legacy_id": "gw-000000oz2", "page": "gri/committee/000000oz2.html", "files": ["심의위원회 심의안건(26-4차).pdf", "(양식) 심의위원회 안건 관련 의견 작성 양식.hwpx"], "source": "gw.gri.re.kr 심의위원회 상정(안)"}'::jsonb,'2026-09-08'::date,'2026-09-08'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000oz2');
