insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'rules','노사협의회 운영규약(2026.5.22.)','<div class="box" style="margin-bottom:16px"><b>노사협의회 운영규약</b> · 작성자 장소희 · 게시일 2026-05-22<br><a href="https://grilu.kr/archive/rules/000000oeq.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">노사협의회 운영규약 일부 개정규약 1. 개 정 이 유   ○ 직제규정 개정에 따른 사용자위원 직책명을 변경하고자 함 2. 개정 주요내용   ○ 사용자 위원 규정 중 기획조정본부장을 행정지원실장으로 변경함 (안 제6조 제3항)</p><p class="note">첨부: 노사협의회 운영규약 일부개정 공포문 (2026.5.22.).pdf</p>','장소희',false,'{"legacy_id": "gw-000000oeq", "page": "archive/rules/000000oeq.html", "files": ["노사협의회 운영규약 일부개정 공포문 (2026.5.22.).pdf"], "source": "gw.gri.re.kr 노사협의회 운영규약"}'::jsonb,'2026-05-22'::date,'2026-05-22'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000oeq');
