insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'guide','2026 공공기관 기록물관리 지침','<div class="box" style="margin-bottom:16px"><b>규정 및 지침</b> · 작성자 이지운 · 게시일 2026-04-27<br><a href="https://grilu.kr/gri/guide/000000o9t.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">국가기록원에서 「2026년 공공기관 기록물관리 지침」을 배포하였기에 해당 지침을 게시합니다. 첨부된 「2026년 공공기관 기록물관리 지침」을 확인하시어, 업무에 참고하시기 바랍니다.</p><p class="note">첨부: 2026 공공기관 기록물관리 지침.pdf</p>','이지운',false,'{"legacy_id": "gw-000000o9t", "page": "gri/guide/000000o9t.html", "files": ["2026 공공기관 기록물관리 지침.pdf"], "source": "gw.gri.re.kr 규정 및 지침"}'::jsonb,'2026-04-27'::date,'2026-04-27'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000o9t');
