insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'guide','공공기관 기록물관리 지침','<div class="box" style="margin-bottom:16px"><b>규정 및 지침</b> · 작성자 이지운 · 게시일 2025-12-30<br><a href="https://grilu.kr/gri/guide/000000ntd.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">안녕하세요, 「공공기관 기록물관리 지침」을 게시합니다. 우리 연구원은 「공공기록물 관리에 관한 법률」 제3조에서 근거한 ‘공공기관’에 해당하므로 연구원에서 업무와 관련하여 생산 및 접수되는 모든 기록정보 자료와 행정박물은 동 법률 및 관련 지침에 따라 체계적으로 관리되어야 합니다. 이에 따라 해당 지침을 게시하오니 업무 시 확인 부탁드립니다. 감사합니다.</p><p class="note">첨부: 2025년공공기관기록물관리지침(국가기록원)_게시.pdf</p>','이지운',false,'{"legacy_id": "gw-000000ntd", "page": "gri/guide/000000ntd.html", "files": ["2025년공공기관기록물관리지침(국가기록원)_게시.pdf"], "source": "gw.gri.re.kr 규정 및 지침"}'::jsonb,'2025-12-30'::date,'2025-12-30'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000ntd');
update public.posts set board='guide', title='공공기관 기록물관리 지침', content='<div class="box" style="margin-bottom:16px"><b>규정 및 지침</b> · 작성자 이지운 · 게시일 2025-12-30<br><a href="https://grilu.kr/gri/guide/000000ntd.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">안녕하세요, 「공공기관 기록물관리 지침」을 게시합니다. 우리 연구원은 「공공기록물 관리에 관한 법률」 제3조에서 근거한 ‘공공기관’에 해당하므로 연구원에서 업무와 관련하여 생산 및 접수되는 모든 기록정보 자료와 행정박물은 동 법률 및 관련 지침에 따라 체계적으로 관리되어야 합니다. 이에 따라 해당 지침을 게시하오니 업무 시 확인 부탁드립니다. 감사합니다.</p><p class="note">첨부: 2025년공공기관기록물관리지침(국가기록원)_게시.pdf</p>', attachments='{"legacy_id": "gw-000000ntd", "page": "gri/guide/000000ntd.html", "files": ["2025년공공기관기록물관리지침(국가기록원)_게시.pdf"], "source": "gw.gri.re.kr 규정 및 지침"}'::jsonb where attachments->>'legacy_id' = 'gw-000000ntd' and (board <> 'guide' or attachments->>'page' <> 'gri/guide/000000ntd.html');
