insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'guide','[개정안내] 일상감사 운영지침','<div class="box" style="margin-bottom:16px"><b>감사</b> · 작성자 송성종 · 게시일 2025-11-04<br><a href="https://grilu.kr/gri/guide/000000ngu.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">감사2025-15998(2025.09.25.)호 “일상감사 운영지침 개정”에 따라 개정된 우리원「일상감사 운영지침」을 다음과 같이 안내 드리오니 업무에 참고하시기 바랍니다. - 주요 개정사항 - 1. 조달청을 통한 제3자 단가계약에 의한 물품구매업무 제외할 수 있는 규정 신설 문의사항이 있으신 경우 감사실 (내선: 217, 208)로 연락주시기 바랍니다. 감사합니다.</p><p class="note">첨부: 1. 경기연구원 일상감사 운영지침(20250929).pdf, 1-1. 일상감사 운영지침 절차 개정 이력.hwp</p>','송성종',false,'{"legacy_id": "gw-000000ngu", "page": "gri/guide/000000ngu.html", "files": ["1. 경기연구원 일상감사 운영지침(20250929).pdf", "1-1. 일상감사 운영지침 절차 개정 이력.hwp"], "source": "gw.gri.re.kr 감사"}'::jsonb,'2025-11-04'::date,'2025-11-04'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000ngu');
