insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'guide','[개정안내] 공정거래 자율준수프로그램(CP) 운영지침','<div class="box" style="margin-bottom:16px"><b>감사</b> · 작성자 송성종 · 게시일 2025-09-25<br><a href="https://grilu.kr/gri/guide/000000ngt.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">감사2025-15997(2025.09.25.)호 “공정거래 자율준수프로그램(CP) 운영지침 개정”에 따라 개정된 우리원「공정거래 자율준수프로그램(CP) 운영지침」을 다음과 같이 안내드립니다. - 주요 개정사항 - 1. 자율준수관리자 변경     기존 부원장 ➡ 감사실장 2. 자율준수위원회 변경     기존 청렴위원회 ➡ 청렴시민감사관회의 3. 위원회 위촉직 위원(공무수행사인) 행위기준 규정 문의사항이 있으신 경우 감사실 (내선: 208, 217)로 연락주시기 바랍니다. 감사합니다.</p><p class="note">첨부: 경기연구원_자율준수 프로그램 운영지침 개정 20250929.pdf, 1-1. GRI CP 기준 및 절차 개정 및 검토이력.hwp</p>','송성종',false,'{"legacy_id": "gw-000000ngt", "page": "gri/guide/000000ngt.html", "files": ["경기연구원_자율준수 프로그램 운영지침 개정 20250929.pdf", "1-1. GRI CP 기준 및 절차 개정 및 검토이력.hwp"], "source": "gw.gri.re.kr 감사"}'::jsonb,'2025-09-25'::date,'2025-09-25'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000ngt');
