insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'guide','GRI연구논총 논문 심사 지침','<div class="box" style="margin-bottom:16px"><b>자료</b> · 작성자 엄예우 · 게시일 2025-05-09<br><a href="https://grilu.kr/gri/guide/000000mvo.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">GRI연구논총 편집위원회 의결 결과에 따라 학술지 투고 논문을 엄정하고 구체적으로 심사하기 위하여 제정된 「GRI연구논총 논문 심사 지침」을 첨부와 같이 안내드립니다. 문의사항은 GRI연구논총 담당자에게 연락 바랍니다.</p><p class="note">첨부: GRI연구논총 논문 심사 지침 제정(안).pdf, GRI연구논총 논문 심사 지침.pdf</p>','엄예우',false,'{"legacy_id": "gw-000000mvo", "page": "gri/guide/000000mvo.html", "files": ["GRI연구논총 논문 심사 지침 제정(안).pdf", "GRI연구논총 논문 심사 지침.pdf"], "source": "gw.gri.re.kr 자료"}'::jsonb,'2025-05-09'::date,'2025-05-09'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000mvo');
