insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'guide','법인카드 사용 및 관리지침','<div class="box" style="margin-bottom:16px"><b>공지</b> · 작성자 박인숙 · 게시일 2025-03-12<br><a href="https://grilu.kr/gri/guide/000000mnt.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">법인카드의 효율적이고 투명한 운영을 위해 사용 및 관리 지침을 마련하였습니다 . 
 모든 직원께서는 지침을 숙지하시어 원활한 업무 수행에 활용해 주시기 바랍니다 . 🔹  주요 내용     ✔  카드 발급 및 반납         •  주요 보직자 · 연구과제 책임자에게 전용카드 지급 ,  미보유자는 공용카드 신청 가능        •  퇴직 · 보직 해임 · 휴직 시 즉시 반납 필수     ✔  사용 원칙 및 제한          •  연구 목적의 공용 용도로만 사용 가능        •  원칙적으로 사전 결재 후 사용  ( 긴급 상황 및 일부 항목은 예외 )        •  개인 경비 · 유흥 · 사행 업종 사용 금지 ,  심야 및 공휴일 사용 제한     ✔  정산 및 관리          •  사용 후  5 일 이내 증빙 제출 필수        •  부정 사용 시 사용액 환수 및 징계 조치        •  법인카드 마일리지는 기관 수익으로 환원    ⇒  자세한 내용은 첨부된 지침을 확인해 주세요 .   법인카드가 보다 효과적으로 운영될 수 있도록 많은 관심과 협조 부탁드립니다 .  ^&amp;^</p><p class="note">첨부: (게시) 법인카드 사용 및 관리 지침.pdf</p>','박인숙',false,'{"legacy_id": "gw-000000mnt", "page": "gri/guide/000000mnt.html", "files": ["(게시) 법인카드 사용 및 관리 지침.pdf"], "source": "gw.gri.re.kr 공지"}'::jsonb,'2025-03-12'::date,'2025-03-12'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000mnt');
