insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'guide','용역사업비 정산 가이드라인','<div class="box" style="margin-bottom:16px"><b>공지</b> · 작성자 박인숙 · 게시일 2025-03-12<br><a href="https://grilu.kr/gri/guide/000000mns.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">위탁용역 사업비정산과 관련하여   체계적인 관리와 원활한 업무 수행 을 위해 「용역사업비 정산 가이드라인」을 마련하였습니다. 
 이 가이드라인에는  정산 집행 원칙, 예산 변경 절차, 참여진 변경 절차, 정산서 제출 방법 등 이 포함되어 있으므로, 위탁용역 사업수행 시 
 참고하여 주시기 바랍니다. 
 📌  주요 내용   ✔ 계약 범위 내 사업비 집행 원칙   ✔ 증빙자료 제출 및 회계 기준 준수   ✔ 예산 변경 및 참여진 변경 승인 절차   ✔ 정산서 제출 및 검토 절차 
 💡  문의 사항이 있을 경우, 재무관리부(선임매니저 박인숙(214번))으로 연락해 주세요. 
  모든 직원분들의 원활한 위탁용역 사업비정산을 위해 적극적인 협조 부탁드립니다.</p><p class="note">첨부: (게시)용역사업비 정산 가이드라인.pdf</p>','박인숙',false,'{"legacy_id": "gw-000000mns", "page": "gri/guide/000000mns.html", "files": ["(게시)용역사업비 정산 가이드라인.pdf"], "source": "gw.gri.re.kr 공지"}'::jsonb,'2025-03-12'::date,'2025-03-12'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000mns');
