insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'council','경기연구원 기관이전 관련 전직원 설문조사 결과보고','<div class="box" style="margin-bottom:16px"><b>공고 및 회의록</b> · 작성자 황지현 · 게시일 2025-02-24<br><a href="https://grilu.kr/archive/council/000000mmt.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">경기연구원 기관이전 관련 전직원 설문조사 결과보고를 붙임과 같이 게시합니다. - 조사대상 : 경기연구원 전직원 - 모집단 수 : 207명(2025. 2. 12. 기준 남101, 여 106) - 응답자 수 : 151명 - 조사기간 : 2025. 2. 10. ~ 2025. 2. 12.(3일간) - 조사방법 : 구글폼을 통한 설문조사</p><p class="note">첨부: (노조)경기연구원 기관이전 관련 전직원 설문조사_결과보고_최종(배포용).pdf</p>','황지현',false,'{"legacy_id": "gw-000000mmt", "page": "archive/council/000000mmt.html", "files": ["(노조)경기연구원 기관이전 관련 전직원 설문조사_결과보고_최종(배포용).pdf"], "source": "gw.gri.re.kr 공고 및 회의록"}'::jsonb,'2025-02-24'::date,'2025-02-24'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000mmt');
