insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'committee','25-1차 심의위원회 상정(안) 게시 및 직원 의견청취 안내','<div class="box" style="margin-bottom:16px"><b>심의위원회 상정(안)</b> · 작성자 장소희 · 게시일 2025-02-17<br><a href="https://grilu.kr/gri/committee/000000mmh.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">심의위원회 상정(안)을 붙임과 같이 게시합니다. 
 ○ 안 건 :  
 - 직제규정 일부 개정(안) 
 - 인사복무규정 일부 개정(안) 
 - 취업규칙 일부 개정(안) 
 - 보수규정 일부 개정(안) 
 - 계약직 운영규칙 일부 개정(안) 
 안건에 대한 의견이 있는 직원은 양식에 따라  ~2월 18일(화) 14:0 0까지 의견을 제출 하여 주시기 바랍니다. 
 *의견 제출방법: 
 (양식)심의위원회 안건 관련 의견 작성→심의위원회 담당자 메일로 제출(인사총무부 장소희, jsh731@gri.kr) 
 감사합니다.</p><p class="note">첨부: 심의위원회 심의안건(25-1).pdf, (양식) 심의위원회 안건 관련 의견 작성 양식.hwpx</p>','장소희',false,'{"legacy_id": "gw-000000mmh", "page": "gri/committee/000000mmh.html", "files": ["심의위원회 심의안건(25-1).pdf", "(양식) 심의위원회 안건 관련 의견 작성 양식.hwpx"], "source": "gw.gri.re.kr 심의위원회 상정(안)"}'::jsonb,'2025-02-17'::date,'2025-02-17'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000mmh');
