insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'rules','노사협의회 운영규약(2024.12.31.)','<div class="box" style="margin-bottom:16px"><b>노사협의회 운영규약</b> · 작성자 장소희 · 게시일 2025-02-13<br><a href="https://grilu.kr/archive/rules/000000mm8.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">2024년 제4차 노사협의회에 따라 일부 개정된 노사협의회 운영규약(2024.12.31.)을 게시합니다.   ○ 개정이유 - 당연직위원인 원장 공석 등의 사유로 노사 각 5명의 위원으로 구성할 수 없는 경우가 발생 - 사용자위원 중 인사발령 등의 사유로 보직자가 변경되는 경우가 발생하므로 행정의 효율성 증대를 위하여 직책명으로 위원을 위촉할 수 있도록 함 ○ 주요 개정사항 - 협의회의 구성을 근로자와 사용자를 대표하는 같은 수의 위원으로 구성하되, 각 3명 이상 10명 이하로 한다고 개정 (안 제6조 제1항) - 사용자 위원을 직책명으로 임명할 수 있도록 개정 (안 제6조 제3항) ○ 신구조문대비표</p><p class="note">첨부: 노사협의회 운영규약(일부 개정안)_241231.pdf</p>','장소희',false,'{"legacy_id": "gw-000000mm8", "page": "archive/rules/000000mm8.html", "files": ["노사협의회 운영규약(일부 개정안)_241231.pdf"], "source": "gw.gri.re.kr 노사협의회 운영규약"}'::jsonb,'2025-02-13'::date,'2025-02-13'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000mm8');
