insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'news','단체교섭 요구사실 공고문','<div class="box" style="margin-bottom:16px"><b>단체교섭</b> · 작성자 정지선 · 게시일 2024-12-10<br><a href="https://grilu.kr/news/news/000000lu3.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">2024.12.10 경기연구원노동조합으로부터 단체교섭 요구가 있어 그 사실을 붙임과 같이 공고합니다.</p><p class="note">첨부: 단체교섭 요구사실 공고문(241210).pdf</p>','정지선',false,'{"legacy_id": "gw-000000lu3", "page": "news/news/000000lu3.html", "files": ["단체교섭 요구사실 공고문(241210).pdf"], "source": "gw.gri.re.kr 단체교섭"}'::jsonb,'2024-12-10'::date,'2024-12-10'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000lu3');
