insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'budget','2025년 경기연구원 예산서','<div class="box" style="margin-bottom:16px"><b>예산결산서</b> · 작성자 민성원 · 게시일 2024-11-29<br><a href="https://grilu.kr/gri/budget/000000lte.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">2025년도 경기연구원 본예산 예산서입니다 
 업무에 참고하시기 바랍니다. 
 ※ 1. 해당 예산서는 지방연구원법에 따라 회계연도 개시 1개월 전까지 도지사 제출을 위해 작성 
    2. 기준은 이사회 의결 기준이며, 출연금 심의는 현재 의회 심의 진행 중 (12.12 의결 예정) 
    3. 향후 의회 의결된 출연금 규모로 추경 진행하여 2025년도 예산 최종 확정</p><p class="note">첨부: 2025년도 경기연구원 본예산_vf.pdf</p>','민성원',false,'{"legacy_id": "gw-000000lte", "page": "gri/budget/000000lte.html", "files": ["2025년도 경기연구원 본예산_vf.pdf"], "source": "gw.gri.re.kr 예산결산서"}'::jsonb,'2024-11-29'::date,'2024-11-29'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000lte');
