insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'committee','24-13차 심의위원회 상정(안) 게시 및 직원 의견청취 안내','<div class="box" style="margin-bottom:16px"><b>심의위원회 상정(안)</b> · 작성자 장소희 · 게시일 2024-11-06<br><a href="https://grilu.kr/gri/committee/000000lsd.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">심의위원회 상정(안)을 붙임과 같이 게시합니다. 
 ○ 안 건 :  
 - 인사복무규정 일부 개정(안) 
 - 취업규칙 일부 개정(안) 
 - 공용차량 관리규칙 일부 개정(안) 
 안건에 대한 의견이 있는 직원은 양식에 따라  ~ 11월 7일(목) 9:3 0까지 의견을 제출 하여 주시기 바랍니다. 
 *의견 제출방법: 
 (양식)심의위원회 안건 관련 의견 작성→심의위원회 담당자 메일로 제출(인사총무부 장소희, jsh731@gri.kr) 
 감사합니다.</p><p class="note">첨부: 심의위원회 심의안건(24-13)_게시.pdf, (양식) 심의위원회 안건 관련 의견 작성 양식.hwpx</p>','장소희',false,'{"legacy_id": "gw-000000lsd", "page": "gri/committee/000000lsd.html", "files": ["심의위원회 심의안건(24-13)_게시.pdf", "(양식) 심의위원회 안건 관련 의견 작성 양식.hwpx"], "source": "gw.gri.re.kr 심의위원회 상정(안)"}'::jsonb,'2024-11-06'::date,'2024-11-06'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000lsd');
