insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'council','2024년도 제3차 노사협의회 결과 및 회의록','<div class="box" style="margin-bottom:16px"><b>공고 및 회의록</b> · 작성자 장소희 · 게시일 2024-10-04<br><a href="https://grilu.kr/archive/council/000000lqx.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">2024년도 제3차 노사협의회 결과 및 회의록을 붙임과 같이 게시합니다.</p><p class="note">첨부: 2024년도 제3차 노사협의회 결과 및 회의록.pdf</p>','장소희',false,'{"legacy_id": "gw-000000lqx", "page": "archive/council/000000lqx.html", "files": ["2024년도 제3차 노사협의회 결과 및 회의록.pdf"], "source": "gw.gri.re.kr 공고 및 회의록"}'::jsonb,'2024-10-04'::date,'2024-10-04'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000lqx');
update public.posts set board='council', title='2024년도 제3차 노사협의회 결과 및 회의록', content='<div class="box" style="margin-bottom:16px"><b>공고 및 회의록</b> · 작성자 장소희 · 게시일 2024-10-04<br><a href="https://grilu.kr/archive/council/000000lqx.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">2024년도 제3차 노사협의회 결과 및 회의록을 붙임과 같이 게시합니다.</p><p class="note">첨부: 2024년도 제3차 노사협의회 결과 및 회의록.pdf</p>', attachments='{"legacy_id": "gw-000000lqx", "page": "archive/council/000000lqx.html", "files": ["2024년도 제3차 노사협의회 결과 및 회의록.pdf"], "source": "gw.gri.re.kr 공고 및 회의록"}'::jsonb where attachments->>'legacy_id' = 'gw-000000lqx' and (board <> 'council' or attachments->>'page' <> 'archive/council/000000lqx.html');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'director','경기연구원 노동이사 공개모집 공고','<div class="box" style="margin-bottom:16px"><b>노동이사 활동보고</b> · 작성자 이용원 · 게시일 2024-10-04<br><a href="https://grilu.kr/gri/director/000000lqw.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">경기연구원 노동이사 선출을 위한 모집 공고가 진행중이니 직원분들께서는 많은 참여 부탁드립니다. -------------------------------------------------------------------------------------------------- 경기연구원은 노동자의 현장 경험과 노하우를 경영에 접목함으로써 경영투명성과 공익성을 확보하고자 아래와 같이 노동이사를 공개 모집합니다. 1.공모직위 및 인원         - 경기연구원 노동이사 1명 2.접수방법         - 접수기간 : 2024. 10. 5.(토) ~ 10. 19.(토) 18:00, 15일간         - 접수방법 : 방문 및 우편접수         - 접 수 처 : 경기연구원 인사총무부           * 주소 : 경기도 수원시 장안구 경수대로 1150 606호(경기연구원 인사총무부)         - 문 의 처 : 경기연구원 인사총무부(031-250-3211) 자세한 사항은 공고문을 확인하여 주시기 바랍니다.</p><p class="note">첨부: GRI 노동이사 공개모집 공고문.hwpx, GRI 노동이사 공개모집 신청서 및 제출서류(양식).hwpx</p>','이용원',false,'{"legacy_id": "gw-000000lqw", "page": "gri/director/000000lqw.html", "files": ["GRI 노동이사 공개모집 공고문.hwpx", "GRI 노동이사 공개모집 신청서 및 제출서류(양식).hwpx"], "source": "gw.gri.re.kr 노동이사 활동보고"}'::jsonb,'2024-10-04'::date,'2024-10-04'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000lqw');
