insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'committee','[답글] 24-10차 심의위원회 상정(안)에 대한 직원 의견 관련 답변서','<div class="box" style="margin-bottom:16px"><b>심의위원회 상정(안)</b> · 작성자 장소희 · 게시일 2024-08-26<br><a href="https://grilu.kr/gri/committee/000000lpd.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">24-10차 심의위원회 상정(안)에 대한 직원 의견 관련 답변서를 붙임과 같이 게시합니다. 
   -----원본메시지-----
 게시자: 장소희
 게시일: 2024.08.05
 제목: 24-10차 심의위원회 상정(안) 게시 및 직원 의견청취 안내
 심의위원회 상정(안)을 붙임과 같이 게시합니다. 
 ○ 안 건 : 근무성적평가규칙 전부 개정규칙(안) 
 안건에 대한 의견이 있는 직원은 양식에 따라  ~ 8월 6일(화) 13:00까지 의견을 제출 하여 주시기 바랍니다. 
     ※ (참고) 7.31(수) 기획조정부 메일 알림 후 제출된 의견은 전달받았습니다. 
 *의견 제출방법: 
 (양식)심의위원회 안건 관련 의견 작성→심의위원회 담당자 메일로 제출(인사총무부 장소희, jsh731@gri.kr) 
 감사합니다.</p><p class="note">첨부: 심의위원회 개최에 따른 직원 의견제안 답변서.pdf</p>','장소희',false,'{"legacy_id": "gw-000000lpd", "page": "gri/committee/000000lpd.html", "files": ["심의위원회 개최에 따른 직원 의견제안 답변서.pdf"], "source": "gw.gri.re.kr 심의위원회 상정(안)"}'::jsonb,'2024-08-26'::date,'2024-08-26'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000lpd');
update public.posts set board='committee', title='[답글] 24-10차 심의위원회 상정(안)에 대한 직원 의견 관련 답변서', content='<div class="box" style="margin-bottom:16px"><b>심의위원회 상정(안)</b> · 작성자 장소희 · 게시일 2024-08-26<br><a href="https://grilu.kr/gri/committee/000000lpd.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">24-10차 심의위원회 상정(안)에 대한 직원 의견 관련 답변서를 붙임과 같이 게시합니다. 
