insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'guide','(수정안내) 일상감사 시행지침','<div class="box" style="margin-bottom:16px"><b>감사</b> · 작성자 손호철 · 게시일 2023-12-22<br><a href="https://grilu.kr/gri/guide/000000lb9.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">자체감사규칙 제29조(일상감사)에 의거하여, 경기연구원 일상감사 시행지침을 첨부와 같이 수정 안내드립니다. ❍ (사유) 일상감사 대상인 &quot;2,000만원 초과 계약업무&quot;에 대한 부가가치세 포함 여부를 명확히 하고자 함. ❍ (개념) 주요 정책의 집행업무 등에 대하여 집행부서와 독립된 감사부서에서 최종 결재권자의 결재에 앞서 그 업무의 적법성․타당성 등을 점검․심사하는 사전 예방적 감사 ❍ (대상업무) ∙ 인사채용(경기도 통합채용 제외, 기간제·단시간 근로자 제외) ∙ 계약업무(2,000만원 초과, 연구과제 제외)  * 부가가치세는 별도로 한다. ∙ 자산 매각 
 ❍ (세부절차) 첨부 참조 궁금하신 사항은 감사실로 문의바랍니다.</p><p class="note">첨부: 경기연구원 일상감사 시행지침(수정안내).hwp</p>','손호철',false,'{"legacy_id": "gw-000000lb9", "page": "gri/guide/000000lb9.html", "files": ["경기연구원 일상감사 시행지침(수정안내).hwp"], "source": "gw.gri.re.kr 감사"}'::jsonb,'2023-12-22'::date,'2023-12-22'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000lb9');
