insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'guide','[안내] 적극행정 세부 운영지침','<div class="box" style="margin-bottom:16px"><b>기타</b> · 작성자 이용원 · 게시일 2023-11-15<br><a href="https://grilu.kr/gri/guide/000000l7w.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">경기연구원 임‧직원의 적극행정을 보호‧지원하고 지속 가능한 적극행정 운영 기반을 마련함으로써 적극적으로 일하는 공직문화를 조성하여 도민의 권익을 보호하고 행정의 적정성을 확보하기 위한 적극행정 세부 운영지침을 첨부와 같이 안내합니다</p><p class="note">첨부: 적극행정 세부 운영지침.pdf</p>','이용원',false,'{"legacy_id": "gw-000000l7w", "page": "gri/guide/000000l7w.html", "files": ["적극행정 세부 운영지침.pdf"], "source": "gw.gri.re.kr 기타"}'::jsonb,'2023-11-15'::date,'2023-11-15'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000l7w');
