insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'committee','23-13차 심의위원회 상정(안) 게시 및 직원 의견청취 관련 안내','<div class="box" style="margin-bottom:16px"><b>심의위원회 상정(안)</b> · 작성자 장소희 · 게시일 2023-08-24<br><a href="https://grilu.kr/gri/committee/000000l2i.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">심의위원회 상정(안)중 규정 규칙 개정 관련 사항을 붙임과 같이 게시합니다. 
 ○ 안 건 : 9건 
 - 직제규정 일부 개정규정(안) 
 - 인사복무규정 일부 개정규정(안) 
 - 보수규정 일부 개정규정(안) 
 - 직원 징계 및 소청 규정 일부 개정규정(안) 
 - 하부조직 및 사무분장규칙 일부 개정규칙(안) 
 - 연구연수 시행규칙 전부 개정규칙(안) 
 - 임직원 행동강령 시행규칙 일부 개정규칙(안) 
 - 연구과제사업 수행규칙 전부 개정규칙(안) 
 - 근무성적평가규칙 일부 개정규칙(안) 
 안건에 대한 의견이 있는 직원은 양식에 따라  ~ 8 월 28 일 ( 월 ) 09:30 까지 의견을 제출 하여 주시기 바랍니다. 
 *의견 제출방법: 
 (양식)심의위원회 안건 관련 의견 작성→심의위원회 담당자 메일로 제출(인사총무부 장소희, jsh731@gri.kr) 
 관련하여 궁금한 사항은 연락주시기 바랍니다. 
 감사합니다.</p><p class="note">첨부: 23-13차 심의위원회 안건자료(8.28).hwp, (양식) 심의위원회 안건 관련 의견 작성 양식 (1).hwpx</p>','장소희',false,'{"legacy_id": "gw-000000l2i", "page": "gri/committee/000000l2i.html", "files": ["23-13차 심의위원회 안건자료(8.28).hwp", "(양식) 심의위원회 안건 관련 의견 작성 양식 (1).hwpx"], "source": "gw.gri.re.kr 심의위원회 상정(안)"}'::jsonb,'2023-08-24'::date,'2023-08-24'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000l2i');
