insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'guide','경기연구원 안전보건관리지침','<div class="box" style="margin-bottom:16px"><b>재난안전(안내, 의견청취 등)</b> · 작성자 장영자 · 게시일 2022-12-19<br><a href="https://grilu.kr/gri/guide/000000kcj.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">경기연구원 안전보건관리지침 
 1. 제정 이유 
 ○ 「중대재해처벌 등에 관한 법률」 시행(’22. 1. 27.)에 따라 중대산업재해의 근원적 예방을 도모하기 위하여 산업안전보건법을 기반으로 안전보건관리체계 구축의 기준이 되는 지침을 제정하고자 함 
 2. 제정 주요내용 
 ○ 제1장 총칙에서 목적, 적용범위, 용어의 정의, 사고예방 책임 명시 
 ○ 제2장 안전보건관리 조직과 직무에서 안전보건관리체제, 체제별 담당 직무 명시 
 ○ 제3장 안전보건위원회 설치 및 운영에서 
 위원회 구성, 개최시기 및 소집, 심의·의결사항, 결과 공지의무 명시 
 ○ 제4장 안전보건교육에서 교육실시의무 명시, 교육대상·시기·시간·교육방법 명시 
 ○ 제5장 유해·위험 방지조치에서 산업재해예방계획 수립, 위험성평가의 실시, 결과의 기록·보존, 안전표지의 설치, 안전 및 보건조치, 재해 발생 시 처리방법 명시 
 ○ 제6장 유해·위험 기계 및 물질에 대한 조치에서 유해하거나 위험한 기계·기구에 대한 방호조치, 직원 준수사항 및 안전보건관리책임자의 조치 명시 
 ○ 제7장 보건 관리에서 건강진단 및 사후관리, 근무환경측정의무 명시 
 3. 지침 : 별첨</p><p class="note">첨부: 경기연구원 안전보건관리지침(제정, 2022.12.19).hwp</p>','장영자',false,'{"legacy_id": "gw-000000kcj", "page": "gri/guide/000000kcj.html", "files": ["경기연구원 안전보건관리지침(제정, 2022.12.19).hwp"], "source": "gw.gri.re.kr 재난안전(안내, 의견청취 등)"}'::jsonb,'2022-12-19'::date,'2022-12-19'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000kcj');
