insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'guide','2023 회계연도 예산안 편성지침','<div class="box" style="margin-bottom:16px"><b>매뉴얼</b> · 작성자 민성원 · 게시일 2022-06-08<br><a href="https://grilu.kr/gri/guide/000000jx3.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">2023 회계연도 예산안 편성지침을 게시합니다. 차년도예산계획서신청 시 첨부문서인 &quot;사업설명자료&quot;는 &quot;양식&quot; 게시판을 확인하여 주시기 바랍니다.</p><p class="note">첨부: 2023 회계연도 예산안 편성지침.hwp, (붙임)2023 회계연도 예산안 목별 공통편성기준v2.hwp, 20220602 GRI 예산비목 길라잡이v3.hwp, 2023년도 지방출자출연기관 예산편성지침 및 집행기준(행안부).hwpx</p>','민성원',false,'{"legacy_id": "gw-000000jx3", "page": "gri/guide/000000jx3.html", "files": ["2023 회계연도 예산안 편성지침.hwp", "(붙임)2023 회계연도 예산안 목별 공통편성기준v2.hwp", "20220602 GRI 예산비목 길라잡이v3.hwp", "2023년도 지방출자출연기관 예산편성지침 및 집행기준(행안부).hwpx"], "source": "gw.gri.re.kr 매뉴얼"}'::jsonb,'2022-06-08'::date,'2022-06-08'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000jx3');
