insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'guide','포스트 오미크론 대응 관련 지방공무원 복무관리지침','<div class="box" style="margin-bottom:16px"><b>코로나19 관련 안내</b> · 작성자 장영자 · 게시일 2022-05-12<br><a href="https://grilu.kr/gri/guide/000000jrn.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">포스트 오미크론 대응 관련 지방공무원 복무관리 지침  시행 안내 
 1. 관련 
 - 코로나바이러스감염증 -19 중앙사고수습본부 -12925(&#x27;22.4.15.) 호 
 - 행정안전부 지방인사제도과 -2940(&#x27;22.4.18.) 호 및 3448(&#x27;22.5.4.) 호 
 - 중앙방역대책본부 -15630(&#x27;22.4.29.) 호 
 2. 위 호와 관련하여 방역완화 조치 등이 시행됨에 따라 , 「 포스트 오미크론 대응 관련 지방공무원 복무관리 지침 」 을 붙임과 같이 통보하오니 , 각 소속기관 및 부서에서는 모든 소속 공무원이 이를 숙지하고 철저히 이행할 수 있도록 필요한 조치를 취하여 주시기 바랍니다 . 
 ○ 적용기간 : &#x27;22.5.4.( 수 ) ~ 별도 통보 시 
 ※ 기존 「 단계적 일상회복을 위한 지방공무원 복무관리 지침 ( 제 1-2 판 ) 」 은 &#x27;22.5.4. 부터 시행되는 「 포스트 오미크론 대응 관련 지방공무원 복무관리 지침 」 으로 대체 
 ○ 지방공무원 주요 복무관리 사항 
 가 . 각 부서별로 부서 내 코로나 19 코로나 19 확산 방지 필요성 등을 종합적으로 감안하여 재택근무 자율 활용 
 ※ 부서 규모 , 소재한 권역 · 지역의 감영상황 ,…</p><p class="note">첨부: 「포스트 오미크론 대응 관련 지방공무원 복무관리 지침」 시행 안내.hwp, 포스트 오미크론 대응 관련 지방공무원 복무관리 지침 (1).hwpx</p>','장영자',false,'{"legacy_id": "gw-000000jrn", "page": "gri/guide/000000jrn.html", "files": ["「포스트 오미크론 대응 관련 지방공무원 복무관리 지침」 시행 안내.hwp", "포스트 오미크론 대응 관련 지방공무원 복무관리 지침 (1).hwpx"], "source": "gw.gri.re.kr 코로나19 관련 안내"}'::jsonb,'2022-05-12'::date,'2022-05-12'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000jrn');
