insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'budget','2022년 경기연구원 예산서','<div class="box" style="margin-bottom:16px"><b>예산결산서</b> · 작성자 민성원 · 게시일 2022-03-10<br><a href="https://grilu.kr/gri/budget/000000jhu.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">2022년 경기연구원 예산서(본예산, 1차추경)를 공지드리오니 업무에 참고하여주시기 바랍니다. 감사합니다.</p><p class="note">첨부: 2022년도 경기연구원 1회추경 예산서_최종.pdf, 2022년도 경기연구원 예산서(본예산) - 최종.pdf</p>','민성원',false,'{"legacy_id": "gw-000000jhu", "page": "gri/budget/000000jhu.html", "files": ["2022년도 경기연구원 1회추경 예산서_최종.pdf", "2022년도 경기연구원 예산서(본예산) - 최종.pdf"], "source": "gw.gri.re.kr 예산결산서"}'::jsonb,'2022-03-10'::date,'2022-03-10'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000jhu');
