insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'council','GRI노사협의회 근로자위원 보궐선거 및 일정 재공고(연구직군)','<div class="box" style="margin-bottom:16px"><b>공고 및 회의록</b> · 작성자 조영진 · 게시일 2022-01-24<br><a href="https://grilu.kr/archive/council/000000jdq.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">GRI노사협의회 근로자위원 보궐선거 및 일정 재공고(연구직군) GRI노사협의회 구성을 위한 연구직군 근로자위원 선거를 아래와 같이 실시함을 재공고합니다. - 아 래 - □ 선거명 노사협의회 근로자위원 선출 보궐선거(연구직군) □ 선출 근로자위원 수 -연구직군 2명 ※선출 근로자위원의 임기는 ~22.8.19까지 □ 입후보자 자격 -현재 경기연구원에 연구직으로 근무 중인 직원(실·부서장 제외) -직원 10명 이상의 추천서를 선거관리위원회에 제출 □ 선거일정 1) 근로자위원 입후보자 등록 : 22.1.24(월) ~ 2.4(금) 2) 입후보자 확정공고 및 선거안내 : 22.2.7(월) 3) 투표일시 : 22.2.8(화), 전자투표 실시 4) 위원선거인 : 재직중인 연구직군 직원(실·부서장 제외) □ 선출방법 1) 위원선거인은 입후보자 중 선호하는 후보자에 투표 2) 득표수가 같을 경우 장기근속자, 연장자순으로 당선자 결정 3) 근로자위원 선출인원과 입후보 인원이 동일할 경우 찬반투표를 실시하며, 유효투표 중 과반수의 찬성으로 근로자 위원 선출결정 직원 여러분들의 많은 참여 바랍니다. 2022. 1. 24 GRI노사협의회 선거관리위원회</p><p class="note">첨부: 220124 GRI노사협의회 근로자위원 보궐선거 및 일정 재공고(연구직군).hwp, 【서식】근로자위원 입후보자추천서.hwp</p>','조영진',false,'{"legacy_id": "gw-000000jdq", "page": "archive/council/000000jdq.html", "files": ["220124 GRI노사협의회 근로자위원 보궐선거 및 일정 재공고(연구직군).hwp", "【서식】근로자위원 입후보자추천서.hwp"], "source": "gw.gri.re.kr 공고 및 회의록"}'::jsonb,'2022-01-24'::date,'2022-01-24'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000jdq');
