insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'council','GRI노사협의회 근로자위원 보궐선거 및 일정 공고','<div class="box" style="margin-bottom:16px"><b>공고 및 회의록</b> · 작성자 조영진 · 게시일 2022-01-17<br><a href="https://grilu.kr/archive/council/000000jbo.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">GRI노사협의회 근로자위원 보궐선거 및 일정 공고 GRI노사협의회 구성을 위한 “근로자위원 선출”을 위한 선거를 아래와 같이 실시함을 공고합니다. - 아 래 - □ 선거명 노사협의회 근로자위원 선출 보궐선거 □ 선출 근로자위원 수 -연구직군 2명 -관리직군 1명 ※선출 근로자위원의 임기는 ~22.8.19까지 □ 선거일정 1) 위원선거인 : 직군별 재직중인 모든 근로자(실·부서장 제외) 2) 근로자위원 입후보자 등록 : 22.1.17(월) ~ 1.21(금), 5일간 3) 입후보자 확정공고 및 선거안내 : 22.1.24(월) 4) 투표일시 : 22.1.25(화), 전자투표 실시 □ 선출방법 1) 직군별 선거인은 입후보자 중 선호하는 후보자에 투표 2) 득표수가 같을 경우 장기근속자, 연장자순으로 당선자 결정 3) 근로자위원 선출인원과 입후보 인원이 동일할 경우 찬반투표를 실시하며, 유효투표 중 과반수의 찬성으로 근로자 위원 선출결정 
 GRI노사협의회 선거관리위원회 
 조영진  
 031-250-3193/powerofsky@gri.kr</p><p class="note">첨부: GRI노사협의회 근로자위원 보궐선거 및 일정 공고(22.1.17).hwp, 【서식】근로자위원 입후보자추천서.hwp</p>','조영진',false,'{"legacy_id": "gw-000000jbo", "page": "archive/council/000000jbo.html", "files": ["GRI노사협의회 근로자위원 보궐선거 및 일정 공고(22.1.17).hwp", "【서식】근로자위원 입후보자추천서.hwp"], "source": "gw.gri.re.kr 공고 및 회의록"}'::jsonb,'2022-01-17'::date,'2022-01-17'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000jbo');
update public.posts set board='council', title='GRI노사협의회 근로자위원 보궐선거 및 일정 공고', content='<div class="box" style="margin-bottom:16px"><b>공고 및 회의록</b> · 작성자 조영진 · 게시일 2022-01-17<br><a href="https://grilu.kr/archive/council/000000jbo.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">GRI노사협의회 근로자위원 보궐선거 및 일정 공고 GRI노사협의회 구성을 위한 “근로자위원 선출”을 위한 선거를 아래와 같이 실시함을 공고합니다. - 아 래 - □ 선거명 노사협의회 근로자위원 선출 보궐선거 □ 선출 근로자위원 수 -연구직군 2명 -관리직군 1명 ※선출 근로자위원의 임기는 ~22.8.19까지 □ 선거일정 1) 위원선거인 : 직군별 재직중인 모든 근로자(실·부서장 제외) 2) 근로자위원 입후보자 등록 : 22.1.17(월) ~ 1.21(금), 5일간 3) 입후보자 확정공고 및 선거안내 : 22.1.24(월) 4) 투표일시 : 22.1.25(화), 전자투표 실시 □ 선출방법 1) 직군별 선거인은 입후보자 중 선호하는 후보자에 투표 2) 득표수가 같을 경우 장기근속자, 연장자순으로 당선자 결정 3) 근로자위원 선출인원과 입후보 인원이 동일할 경우 찬반투표를 실시하며, 유효투표 중 과반수의 찬성으로 근로자 위원 선출결정 
 GRI노사협의회 선거관리위원회 
 조영진  
 031-250-3193/powerofsky@gri.kr</p><p class="note">첨부: GRI노사협의회 근로자위원 보궐선거 및 일정 공고(22.1.17).hwp, 【서식】근로자위원 입후보자추천서.hwp</p>', attachments='{"legacy_id": "gw-000000jbo", "page": "archive/council/000000jbo.html", "files": ["GRI노사협의회 근로자위원 보궐선거 및 일정 공고(22.1.17).hwp", "【서식】근로자위원 입후보자추천서.hwp"], "source": "gw.gri.re.kr 공고 및 회의록"}'::jsonb where attachments->>'legacy_id' = 'gw-000000jbo' and (board <> 'council' or attachments->>'page' <> 'archive/council/000000jbo.html');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'council','GRI노사협의회 근로자위원 선출을 위한 선거관리위원회 구성결과 공고','<div class="box" style="margin-bottom:16px"><b>공고 및 회의록</b> · 작성자 장영자 · 게시일 2022-01-13<br><a href="https://grilu.kr/archive/council/000000jbg.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">GRI 노사협의회 근로자위원 선출을 위한 선거관리위원회 구성 결과 공고 
 GRI 노사협의회 근로자위원 선출 을 위한 선거관리위원회가 아래와 같이 구성되었음을 공고합니다 . 
 - 아 래 - 
 □ 선거관리위원회 위원명단 
 - 조영무 연구위원 ( 시군연구센터 ) 
 - 조영진 연구원 ( 대외협력부 ) 
 □ 선거관리위원회 수행임무 
  1. 선거 및 일정공고 
  2. 투표 및 입후보자 등록 등에 관한사항 
  3. 당선자 결정에 관한 사항 
  4. 기타 선거와 관련된 사항 
 □ 향후 절차 
  • 근로자 위원 선출공고 
  • 근로자 위원 후보등록 
  • 선출투표 실시 ( 직접 · 비밀 · 무기명 투표 )</p>','장영자',false,'{"legacy_id": "gw-000000jbg", "page": "archive/council/000000jbg.html", "files": [], "source": "gw.gri.re.kr 공고 및 회의록"}'::jsonb,'2022-01-13'::date,'2022-01-13'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000jbg');
