insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'council','GRI노사협의회 근로자위원 선출을 위한 선거관리위원회 구성공고','<div class="box" style="margin-bottom:16px"><b>공고 및 회의록</b> · 작성자 장영자 · 게시일 2022-01-10<br><a href="https://grilu.kr/archive/council/000000jba.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">&lt;GRI노사협의회 근로자위원 선출을 위한 선거관리위원회 구성 공고&gt; GRI노사협의회 근로자위원 궐위(공석 3명) 에 따라 노사협의회운영규약 제3장 제11조(선거관리위원회 구성)에 의거 
 GRI노사협의회 근로자위원 선출(3명 선출) 을 위한 선거관리위원회 를 아래와 같이 구성 하고자 합니다. 선거관리위원회 위원으로 참여를 희망하는 직원 은 22.1.12(수)까지 신청 하여 주시기 바랍니다. 
 (담당자 행정지원부 장영자과장(내선 269)) 
                                                         - 아 래 - □ 선거관리위원회 위원수:   선거관리 참여 희망 근로자 중 추첨에 의하여 2명 구성   ※선거관리위원회 위원은 향후 근로자위원에 입후보 불가 □ 선거관리위원회 구성기한:   선거공고일 14일 전까지 구성 □ 선거관리위원회 수행임무:   1. 선거 및 일정공고   2. 투표 및 입후보자 등록등에 관한사항   3. 당선자 결정에 관한 사항   4. 기타 선거와 관련된 사항 
 참고 . GRI 노사협의회 근로자위원 구성현황 
 구 분 
 근로자 측 
 성 명 
 직 위 
 위촉기간 
 대표위원 
 ( 공석 ) …</p>','장영자',false,'{"legacy_id": "gw-000000jba", "page": "archive/council/000000jba.html", "files": [], "source": "gw.gri.re.kr 공고 및 회의록"}'::jsonb,'2022-01-10'::date,'2022-01-10'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000jba');
