insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'director','경기연구원 노동이사 선거결과공고','<div class="box" style="margin-bottom:16px"><b>노동이사 활동보고</b> · 작성자 송성종 · 게시일 2021-12-14<br><a href="https://grilu.kr/gri/director/000000j6b.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">경기연구원 노동이사 후보자 선거결과를 아래와 같이 공고합니다. 
 * 투표율 : 78.5%(150명 / 191명) 
   선거인 수(191명), 투표인 수(150명), 유효투표 수(150명), 무효투표 수(0명), 기권 수(41명, 퇴사자 2명 포함) 
   기호1번 송제룡 득표수 55(36.7%) 
   기호2번 조영무 득표수 95(63.3%) 
 * 최종 당선자는 향후 이사회 의결을거쳐 도지사 임명예정입니다. 
 * 선거결과에 대한 이의신청은 공고 후 10일 내 선거관리위원회로 신청할 수 있습니다</p>','송성종',false,'{"legacy_id": "gw-000000j6b", "page": "gri/director/000000j6b.html", "files": [], "source": "gw.gri.re.kr 노동이사 활동보고"}'::jsonb,'2021-12-14'::date,'2021-12-14'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000j6b');
