insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'director','경기연구원 노동이사 후보자 사퇴 공고','<div class="box" style="margin-bottom:16px"><b>노동이사 활동보고</b> · 작성자 송성종 · 게시일 2021-12-09<br><a href="https://grilu.kr/gri/director/000000j64.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">경기연구원 노동이사 후보자사퇴 공고 2021년 12월 13일 실시하는 경기연구원 노동이사 선거에 있어 후보자 사퇴를 다음과 같이 공고합니다. ▶ 선   거   명: 경기연구원 노동이사 선거 ▶ 기         호: 3번 ▶ 성         명: 김점산 ▶ 사퇴연월일: 2021년 12월 9일 ※ 자세한 내용은 첨부드린 공고문 참조 부탁드립니다.</p><p class="note">첨부: 후보자 사퇴공고문.pdf</p>','송성종',false,'{"legacy_id": "gw-000000j64", "page": "gri/director/000000j64.html", "files": ["후보자 사퇴공고문.pdf"], "source": "gw.gri.re.kr 노동이사 활동보고"}'::jsonb,'2021-12-09'::date,'2021-12-09'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000j64');
