insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'director','경기연구원 노동이사 입후보자 및 선거일정공고','<div class="box" style="margin-bottom:16px"><b>노동이사 활동보고</b> · 작성자 송성종 · 게시일 2021-12-01<br><a href="https://grilu.kr/gri/director/000000j5l.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">경기연구원 노동이사 입후보자 및 선거일정을 아래와 같이 공고합니다. 후보자별 선거공부 및 직무수행계획서는 첨부파일 참조 부탁 드립니다.</p><p class="note">첨부: 입후보자 및 선거공고.pdf, 입후보자직무수행계획서(송제룡).pdf, 입후보자직무수행계획서(조영무).pdf, 입후보자직무수행계획서(김점산).pdf</p>','송성종',false,'{"legacy_id": "gw-000000j5l", "page": "gri/director/000000j5l.html", "files": ["입후보자 및 선거공고.pdf", "입후보자직무수행계획서(송제룡).pdf", "입후보자직무수행계획서(조영무).pdf", "입후보자직무수행계획서(김점산).pdf"], "source": "gw.gri.re.kr 노동이사 활동보고"}'::jsonb,'2021-12-01'::date,'2021-12-01'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000j5l');
