insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'budget','2021년 경기연구원 예산서(제2회추경반영)_0827','<div class="box" style="margin-bottom:16px"><b>예산결산서</b> · 작성자 민성원 · 게시일 2021-08-27<br><a href="https://grilu.kr/gri/budget/000000j0t.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">2021년 경기연구원 제 2회 추경예산을 반영한 예산서를 공지드리오니 업무에 참고하여주시기 바랍니다. 감사합니다.</p><p class="note">첨부: 2021년도 경기연구원 예산서-제2회추경.pdf</p>','민성원',false,'{"legacy_id": "gw-000000j0t", "page": "gri/budget/000000j0t.html", "files": ["2021년도 경기연구원 예산서-제2회추경.pdf"], "source": "gw.gri.re.kr 예산결산서"}'::jsonb,'2021-08-27'::date,'2021-08-27'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000j0t');
update public.posts set board='budget', title='2021년 경기연구원 예산서(제2회추경반영)_0827', content='<div class="box" style="margin-bottom:16px"><b>예산결산서</b> · 작성자 민성원 · 게시일 2021-08-27<br><a href="https://grilu.kr/gri/budget/000000j0t.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">2021년 경기연구원 제 2회 추경예산을 반영한 예산서를 공지드리오니 업무에 참고하여주시기 바랍니다. 감사합니다.</p><p class="note">첨부: 2021년도 경기연구원 예산서-제2회추경.pdf</p>', attachments='{"legacy_id": "gw-000000j0t", "page": "gri/budget/000000j0t.html", "files": ["2021년도 경기연구원 예산서-제2회추경.pdf"], "source": "gw.gri.re.kr 예산결산서"}'::jsonb where attachments->>'legacy_id' = 'gw-000000j0t' and (board <> 'budget' or attachments->>'page' <> 'gri/budget/000000j0t.html');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'director','경기연구원 노동이사 활동사항 보고(2020. 5. 27- 2021.5.26)','<div class="box" style="margin-bottom:16px"><b>노동이사 활동보고</b> · 작성자 이상훈 · 게시일 2021-05-25<br><a href="https://grilu.kr/gri/director/000000iv3.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">경기연구원 노동이사 활동사항(2020. 5. 27 -2021. 5. 26)을 첨부와 같이 보고합니다.</p><p class="note">첨부: GRI 노동이사 활동사항 보고(2020-2021).hwp</p>','이상훈',false,'{"legacy_id": "gw-000000iv3", "page": "gri/director/000000iv3.html", "files": ["GRI 노동이사 활동사항 보고(2020-2021).hwp"], "source": "gw.gri.re.kr 노동이사 활동보고"}'::jsonb,'2021-05-25'::date,'2021-05-25'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000iv3');
update public.posts set board='director', title='경기연구원 노동이사 활동사항 보고(2020. 5. 27- 2021.5.26)', content='<div class="box" style="margin-bottom:16px"><b>노동이사 활동보고</b> · 작성자 이상훈 · 게시일 2021-05-25<br><a href="https://grilu.kr/gri/director/000000iv3.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">경기연구원 노동이사 활동사항(2020. 5. 27 -2021. 5. 26)을 첨부와 같이 보고합니다.</p><p class="note">첨부: GRI 노동이사 활동사항 보고(2020-2021).hwp</p>', attachments='{"legacy_id": "gw-000000iv3", "page": "gri/director/000000iv3.html", "files": ["GRI 노동이사 활동사항 보고(2020-2021).hwp"], "source": "gw.gri.re.kr 노동이사 활동보고"}'::jsonb where attachments->>'legacy_id' = 'gw-000000iv3' and (board <> 'director' or attachments->>'page' <> 'gri/director/000000iv3.html');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'guide','[안내] 일상감사 시행지침','<div class="box" style="margin-bottom:16px"><b>감사</b> · 작성자 이용원 · 게시일 2021-05-14<br><a href="https://grilu.kr/gri/guide/000000iun.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">금일 결재문서를 기 공람해 드린 바와 같이, 자체감사규칙 제29조(일상감사)에 의거하여, 경기연구원 일상감사 시행지침을 첨부와 같이 알려드리오니, 이를 숙지하여 차질없이 이행하여 주시기 바랍니다.   ❍ (개념) 주요 정책의 집행업무 등에 대하여 집행부서와 독립된 감사부서에서 최종 결재권자의 결재에 앞서                 그 업무의 적법성․타당성 등을 점검․심사하는 사전 예방적 감사   ❍ (대상업무)     ∙ 인사채용(경기도 통합채용 제외, 기간제·단시간 근로자 제외)     ∙ 계약업무(2,000만원 초과, 연구과제 제외)     ∙ 자산 매각   ❍ (시행시기) : 2021. 6.1   ❍ (세부절차) 첨부 참조 궁금하신 사항은  감사실로 문의바랍니다.</p><p class="note">첨부: 경기연구원 일상감사 시행지침(안내).hwp</p>','이용원',false,'{"legacy_id": "gw-000000iun", "page": "gri/guide/000000iun.html", "files": ["경기연구원 일상감사 시행지침(안내).hwp"], "source": "gw.gri.re.kr 감사"}'::jsonb,'2021-05-14'::date,'2021-05-14'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000iun');
update public.posts set board='guide', title='[안내] 일상감사 시행지침', content='<div class="box" style="margin-bottom:16px"><b>감사</b> · 작성자 이용원 · 게시일 2021-05-14<br><a href="https://grilu.kr/gri/guide/000000iun.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">금일 결재문서를 기 공람해 드린 바와 같이, 자체감사규칙 제29조(일상감사)에 의거하여, 경기연구원 일상감사 시행지침을 첨부와 같이 알려드리오니, 이를 숙지하여 차질없이 이행하여 주시기 바랍니다.   ❍ (개념) 주요 정책의 집행업무 등에 대하여 집행부서와 독립된 감사부서에서 최종 결재권자의 결재에 앞서                 그 업무의 적법성․타당성 등을 점검․심사하는 사전 예방적 감사   ❍ (대상업무)     ∙ 인사채용(경기도 통합채용 제외, 기간제·단시간 근로자 제외)     ∙ 계약업무(2,000만원 초과, 연구과제 제외)     ∙ 자산 매각   ❍ (시행시기) : 2021. 6.1   ❍ (세부절차) 첨부 참조 궁금하신 사항은  감사실로 문의바랍니다.</p><p class="note">첨부: 경기연구원 일상감사 시행지침(안내).hwp</p>', attachments='{"legacy_id": "gw-000000iun", "page": "gri/guide/000000iun.html", "files": ["경기연구원 일상감사 시행지침(안내).hwp"], "source": "gw.gri.re.kr 감사"}'::jsonb where attachments->>'legacy_id' = 'gw-000000iun' and (board <> 'guide' or attachments->>'page' <> 'gri/guide/000000iun.html');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'guide','객원 연구원 운영지침','<div class="box" style="margin-bottom:16px"><b>매뉴얼</b> · 작성자 정형기 · 게시일 2021-04-20<br><a href="https://grilu.kr/gri/guide/000000itk.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">&lt; 추진 배경&gt; ◇ 경기연구원을 포함 다수 대학이나 연구기관 등에서는 연구연수(안식년) 제도가 있으며, 연구자문 공동연구 및     연구인력교류와 협력 활성화 차원에서 상호호혜의 원칙하에 객원연구원 또는 방문연구원 등의 제도를 운영하고 있음 ◇ 코로나19로 인해 해외 연구연수에 제약이 많아지면서, 우리원의 객원연구원 운영에     대한 문의가 증가함에 따라 이에 대한 운영 근거 및 기준 마련이 요구됨 1. 객원연구원 자격요건   ○ 국내외 연구기관의 박사급 이상 연구원(GRI 연구위원 가급 상당 해당자)   ○ 국내외 대학의 조교수급 이상   ○ 기타 관련분야에 전문지식과 경험이 풍부한 자로 원장이 인정하는 자 2. 선정절차   ○ 해당기관 공문 수신   ○ 공문내용 &amp; 자격요건 확인 및 내부결재 진행      - (결재) 연구기획부장 – 연구기획본부장 – 연구부원장 - 원장      - (협조) 해당 연구부서장, 행정지원부장, 홍보정보부장   ○ 해당기관에 회신 공문 발송 3. 지원내용   ○ (공  간) 스마트 오피스 제공 (북부연구센터와 별도 운영) : 공용 PC, 인터넷, 전화기 등   ○ (인프라) 정보자료실 출입 및 이용 : 국내외 저널 이용 등 …</p><p class="note">첨부: 객원연구원 운영지침(게시).hwp</p>','정형기',false,'{"legacy_id": "gw-000000itk", "page": "gri/guide/000000itk.html", "files": ["객원연구원 운영지침(게시).hwp"], "source": "gw.gri.re.kr 매뉴얼"}'::jsonb,'2021-04-20'::date,'2021-04-20'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000itk');
update public.posts set board='guide', title='객원 연구원 운영지침', content='<div class="box" style="margin-bottom:16px"><b>매뉴얼</b> · 작성자 정형기 · 게시일 2021-04-20<br><a href="https://grilu.kr/gri/guide/000000itk.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">&lt; 추진 배경&gt; ◇ 경기연구원을 포함 다수 대학이나 연구기관 등에서는 연구연수(안식년) 제도가 있으며, 연구자문 공동연구 및     연구인력교류와 협력 활성화 차원에서 상호호혜의 원칙하에 객원연구원 또는 방문연구원 등의 제도를 운영하고 있음 ◇ 코로나19로 인해 해외 연구연수에 제약이 많아지면서, 우리원의 객원연구원 운영에     대한 문의가 증가함에 따라 이에 대한 운영 근거 및 기준 마련이 요구됨 1. 객원연구원 자격요건   ○ 국내외 연구기관의 박사급 이상 연구원(GRI 연구위원 가급 상당 해당자)   ○ 국내외 대학의 조교수급 이상   ○ 기타 관련분야에 전문지식과 경험이 풍부한 자로 원장이 인정하는 자 2. 선정절차   ○ 해당기관 공문 수신   ○ 공문내용 &amp; 자격요건 확인 및 내부결재 진행      - (결재) 연구기획부장 – 연구기획본부장 – 연구부원장 - 원장      - (협조) 해당 연구부서장, 행정지원부장, 홍보정보부장   ○ 해당기관에 회신 공문 발송 3. 지원내용   ○ (공  간) 스마트 오피스 제공 (북부연구센터와 별도 운영) : 공용 PC, 인터넷, 전화기 등   ○ (인프라) 정보자료실 출입 및 이용 : 국내외 저널 이용 등 …</p><p class="note">첨부: 객원연구원 운영지침(게시).hwp</p>', attachments='{"legacy_id": "gw-000000itk", "page": "gri/guide/000000itk.html", "files": ["객원연구원 운영지침(게시).hwp"], "source": "gw.gri.re.kr 매뉴얼"}'::jsonb where attachments->>'legacy_id' = 'gw-000000itk' and (board <> 'guide' or attachments->>'page' <> 'gri/guide/000000itk.html');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'guide','경기연구원 직장내 괴롭힘 금지지침','<div class="box" style="margin-bottom:16px"><b>갑질(직장내 괴롭힘등) 신고센터</b> · 작성자 장영자 · 게시일 2021-02-24<br><a href="https://grilu.kr/gri/guide/000000ipc.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">경기연구원 직장내 괴롭힘 금지지침을 게시합니다.</p><p class="note">첨부: 경기연구원 직장내 괴롭힘 금지 지침(2019.7.16).hwp</p>','장영자',false,'{"legacy_id": "gw-000000ipc", "page": "gri/guide/000000ipc.html", "files": ["경기연구원 직장내 괴롭힘 금지 지침(2019.7.16).hwp"], "source": "gw.gri.re.kr 갑질(직장내 괴롭힘등) 신고센터"}'::jsonb,'2021-02-24'::date,'2021-02-24'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000ipc');
