insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'guide','경기연구원 노동이사 운영지침','<div class="box" style="margin-bottom:16px"><b>매뉴얼</b> · 작성자 정형기 · 게시일 2020-12-22<br><a href="https://grilu.kr/gri/guide/000000ilj.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">□ 제정 목적     ○ 소통과 협치를 위한 경영 패러다임 전환으로 연구원 경쟁력 제고    ○ 노동이사의 권한을 확대하여 근로자의 권익향상에 기여    ○ 노동이사의 역할ㆍ권한 정립 및 실질적 활동 지원       - 관련 법령상 규정된 비상임 이사와 동등한 권한 및 책임 부여       - 경영 전문성 확보를 위한 자체 교육프로그램 운영 등 역량강화 지원   □ 주요 조항     ○ 노동이사의 권한      : 이사회 참여 및 의결권, 이사회 안건 제출권, 정보열람권 부여        (비공개 정보 제외)    ○ 노동이사의 의무 : 성실의무, 품위유지 등    ○ 기관장 책무 : 교육 및 훈련기회 부여, 인사상 불이익 조치 금지     ○ 노동이사 임기 : 3년, 단 근로관계 종료 및 중징계시 노동이사 임기 만료    ○ 노동이사 지원 : 무보수, 단 이사회에 참석할 경우 안건 및 자료                      검토에 소요되는 수당, 대근로자 활동비 지급</p><p class="note">첨부: 경기연구원 노동이사 운영지침.hwp</p>','정형기',false,'{"legacy_id": "gw-000000ilj", "page": "gri/guide/000000ilj.html", "files": ["경기연구원 노동이사 운영지침.hwp"], "source": "gw.gri.re.kr 매뉴얼"}'::jsonb,'2020-12-22'::date,'2020-12-22'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000ilj');
update public.posts set board='guide', title='경기연구원 노동이사 운영지침', content='<div class="box" style="margin-bottom:16px"><b>매뉴얼</b> · 작성자 정형기 · 게시일 2020-12-22<br><a href="https://grilu.kr/gri/guide/000000ilj.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">□ 제정 목적     ○ 소통과 협치를 위한 경영 패러다임 전환으로 연구원 경쟁력 제고    ○ 노동이사의 권한을 확대하여 근로자의 권익향상에 기여    ○ 노동이사의 역할ㆍ권한 정립 및 실질적 활동 지원       - 관련 법령상 규정된 비상임 이사와 동등한 권한 및 책임 부여       - 경영 전문성 확보를 위한 자체 교육프로그램 운영 등 역량강화 지원   □ 주요 조항     ○ 노동이사의 권한      : 이사회 참여 및 의결권, 이사회 안건 제출권, 정보열람권 부여        (비공개 정보 제외)    ○ 노동이사의 의무 : 성실의무, 품위유지 등    ○ 기관장 책무 : 교육 및 훈련기회 부여, 인사상 불이익 조치 금지     ○ 노동이사 임기 : 3년, 단 근로관계 종료 및 중징계시 노동이사 임기 만료    ○ 노동이사 지원 : 무보수, 단 이사회에 참석할 경우 안건 및 자료                      검토에 소요되는 수당, 대근로자 활동비 지급</p><p class="note">첨부: 경기연구원 노동이사 운영지침.hwp</p>', attachments='{"legacy_id": "gw-000000ilj", "page": "gri/guide/000000ilj.html", "files": ["경기연구원 노동이사 운영지침.hwp"], "source": "gw.gri.re.kr 매뉴얼"}'::jsonb where attachments->>'legacy_id' = 'gw-000000ilj' and (board <> 'guide' or attachments->>'page' <> 'gri/guide/000000ilj.html');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'guide','재택근무 관련 복무지침','<div class="box" style="margin-bottom:16px"><b>매뉴얼</b> · 작성자 장영자 · 게시일 2020-11-24<br><a href="https://grilu.kr/gri/guide/000000ikf.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">재택근무 관련 복무지침 개정내용을 게시합니다.</p><p class="note">첨부: 붙임. 재택근무 관련 복무지침(2020.12.8).hwp</p>','장영자',false,'{"legacy_id": "gw-000000ikf", "page": "gri/guide/000000ikf.html", "files": ["붙임. 재택근무 관련 복무지침(2020.12.8).hwp"], "source": "gw.gri.re.kr 매뉴얼"}'::jsonb,'2020-11-24'::date,'2020-11-24'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000ikf');
