insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'budget','2020년도 경기연구원 수입지출예산서(제2회 추경 반영)','<div class="box" style="margin-bottom:16px"><b>예산결산서</b> · 작성자 박정환 · 게시일 2020-08-25<br><a href="https://grilu.kr/gri/budget/000000igd.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">제105차 임시이사회에서 승인된 예산서를 공지합니다. 
