insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'director','경기연구원 노동이사 선거결과공고','<div class="box" style="margin-bottom:16px"><b>노동이사 활동보고</b> · 작성자 이대민 · 게시일 2020-04-16<br><a href="https://grilu.kr/gri/director/000000i72.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">경기연구원 노동이사 후보자 선거결과를 아래와 같이 공고합니다 
 * 투표율 : 82.5%(142명 / 172명) 
   선거인 수(172명), 투표인 수(142명), 유효투표 수(142명), 무효투표 수(0명), 기권 수(30명, 퇴사자3명 포함) 
   기호1번 이상훈 득표수 95(66.9%) 
   기호2번 고재경 득표수 47(33.1%) 
 * 최종 당선자는 향후 이사회 의결을거쳐 도지사 임명예정입니다 
 * 선거결과에 대한 이의신청은 공고 후 10일 내 선거관리위원회로 신청할 수 있습니다</p>','이대민',false,'{"legacy_id": "gw-000000i72", "page": "gri/director/000000i72.html", "files": [], "source": "gw.gri.re.kr 노동이사 활동보고"}'::jsonb,'2020-04-16'::date,'2020-04-16'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000i72');
update public.posts set board='director', title='경기연구원 노동이사 선거결과공고', content='<div class="box" style="margin-bottom:16px"><b>노동이사 활동보고</b> · 작성자 이대민 · 게시일 2020-04-16<br><a href="https://grilu.kr/gri/director/000000i72.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">경기연구원 노동이사 후보자 선거결과를 아래와 같이 공고합니다 
 * 투표율 : 82.5%(142명 / 172명) 
   선거인 수(172명), 투표인 수(142명), 유효투표 수(142명), 무효투표 수(0명), 기권 수(30명, 퇴사자3명 포함) 
   기호1번 이상훈 득표수 95(66.9%) 
   기호2번 고재경 득표수 47(33.1%) 
 * 최종 당선자는 향후 이사회 의결을거쳐 도지사 임명예정입니다 
 * 선거결과에 대한 이의신청은 공고 후 10일 내 선거관리위원회로 신청할 수 있습니다</p>', attachments='{"legacy_id": "gw-000000i72", "page": "gri/director/000000i72.html", "files": [], "source": "gw.gri.re.kr 노동이사 활동보고"}'::jsonb where attachments->>'legacy_id' = 'gw-000000i72' and (board <> 'director' or attachments->>'page' <> 'gri/director/000000i72.html');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'director','경기연구원 노동이사 입후보자 및 선거일정공고','<div class="box" style="margin-bottom:16px"><b>노동이사 활동보고</b> · 작성자 이대민 · 게시일 2020-04-06<br><a href="https://grilu.kr/gri/director/000000i6h.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">경기연구원 노동이사 입후보자 및 선거일정을 아래와 같이 공고합니다 
 후보자별 선거공보 및 직무수행계획서는 첨부파일 참조 부탁드립니다</p><p class="note">첨부: 입후보자 공고문 및 선거공보.pdf, 입후보자 직무수행계획서(이상훈).hwp, 입후보자 직무수행계획서(고재경).hwp</p>','이대민',false,'{"legacy_id": "gw-000000i6h", "page": "gri/director/000000i6h.html", "files": ["입후보자 공고문 및 선거공보.pdf", "입후보자 직무수행계획서(이상훈).hwp", "입후보자 직무수행계획서(고재경).hwp"], "source": "gw.gri.re.kr 노동이사 활동보고"}'::jsonb,'2020-04-06'::date,'2020-04-06'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000i6h');
update public.posts set board='director', title='경기연구원 노동이사 입후보자 및 선거일정공고', content='<div class="box" style="margin-bottom:16px"><b>노동이사 활동보고</b> · 작성자 이대민 · 게시일 2020-04-06<br><a href="https://grilu.kr/gri/director/000000i6h.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">경기연구원 노동이사 입후보자 및 선거일정을 아래와 같이 공고합니다 
 후보자별 선거공보 및 직무수행계획서는 첨부파일 참조 부탁드립니다</p><p class="note">첨부: 입후보자 공고문 및 선거공보.pdf, 입후보자 직무수행계획서(이상훈).hwp, 입후보자 직무수행계획서(고재경).hwp</p>', attachments='{"legacy_id": "gw-000000i6h", "page": "gri/director/000000i6h.html", "files": ["입후보자 공고문 및 선거공보.pdf", "입후보자 직무수행계획서(이상훈).hwp", "입후보자 직무수행계획서(고재경).hwp"], "source": "gw.gri.re.kr 노동이사 활동보고"}'::jsonb where attachments->>'legacy_id' = 'gw-000000i6h' and (board <> 'director' or attachments->>'page' <> 'gri/director/000000i6h.html');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'council','경기연구원 사내근로복지기금 안내','<div class="box" style="margin-bottom:16px"><b>공고 및 회의록</b> · 작성자 장영자 · 게시일 2020-04-02<br><a href="https://grilu.kr/archive/council/000000i63.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">직원의 생활안정과 복지증진에 사용하기 위해 연구원 이익금을 출연해 설립한 &#x27;경기연구원 사내근로복지기금&#x27;은 2009년 설립되어 현재까지 운용되고 있으며, 기금의 수익금(이자수익 등)으로 체육문화활동지원, 근로자의 날 행사 지원 등의 사업을 수행하여왔습니다. 이와 관련하여 경기연구원 사내근로복지기금 정관 및 2020년도 사업계획을 첨부하오니 참고하시기 바랍니다. -  사내근로복지기금 협의회 및 이사회 구성  - &lt;사내근로복지기금 협의회&gt; 위    원 : 김재용, 송미영, 박인숙 위    원 : 강철구, 석동근, 조희은 &lt;이사회&gt; 대표이사 : 김재용, 이은환 이      사 : 손호철, 박원익 감      사 : 정형기, 김은경</p><p class="note">첨부: 정관.hwp, 2020년도 사업계획서(경기연구원사내근로복지기금).pdf</p>','장영자',false,'{"legacy_id": "gw-000000i63", "page": "archive/council/000000i63.html", "files": ["정관.hwp", "2020년도 사업계획서(경기연구원사내근로복지기금).pdf"], "source": "gw.gri.re.kr 공고 및 회의록"}'::jsonb,'2020-04-02'::date,'2020-04-02'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000i63');
