insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'council','취업규칙 게시','<div class="box" style="margin-bottom:16px"><b>공고 및 회의록</b> · 작성자 정형기 · 게시일 2019-12-17<br><a href="https://grilu.kr/archive/council/000000hvo.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">고용노동부에 신고한 취업규칙을 첨부와 같이 게시합니다.</p><p class="note">첨부: 2019년 취업규칙(전문)(2019.12.17).hwp</p>','정형기',false,'{"legacy_id": "gw-000000hvo", "page": "archive/council/000000hvo.html", "files": ["2019년 취업규칙(전문)(2019.12.17).hwp"], "source": "gw.gri.re.kr 공고 및 회의록"}'::jsonb,'2019-12-17'::date,'2019-12-17'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000hvo');
