insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'guide','임산부 연장근로 금지 운영 지침','<div class="box" style="margin-bottom:16px"><b>매뉴얼</b> · 작성자 정용욱 · 게시일 2019-08-30<br><a href="https://grilu.kr/gri/guide/000000hof.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">현재 근로기준법에서는 임신중인 여성노동자의 장시간 노동을 방지하고 시간외근로를 하지 못하도록 제한하고 있습니다. 이에 전직원은 이를 숙지하여 주시기 바랍니다.</p><p class="note">첨부: 임산부연장근로금지운영지침.pdf</p>','정용욱',false,'{"legacy_id": "gw-000000hof", "page": "gri/guide/000000hof.html", "files": ["임산부연장근로금지운영지침.pdf"], "source": "gw.gri.re.kr 매뉴얼"}'::jsonb,'2019-08-30'::date,'2019-08-30'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000hof');
